/**
 * Print every migration's DDL as one paste-able script.
 *
 *   npm run --silent migrations:print > migrations-to-run.sql
 *
 * (`--silent` matters: without it npm writes its own banner to stdout and the
 * first two lines of the generated file are not SQL.)
 *
 * WHY THIS EXISTS
 * The migrations can be applied two ways: `npm run migrate:*` with a
 * DATABASE_URL, or by pasting SQL into the Supabase editor. The paste route is
 * how this project's migrations have actually been applied so far, and a
 * hand-maintained copy of the DDL is a copy that drifts — the version that runs
 * in production silently stops being the version in the migration file.
 *
 * So the paste-able file is GENERATED from the same MIGRATION_SQL constants the
 * runners execute. There is one source of truth.
 *
 * No database connection is made. `postgres()` is lazy, so importing the
 * migration modules only needs DATABASE_URL to be *present*, not valid — hence
 * the placeholder below for the common case of running this without an env file.
 */
process.env.DATABASE_URL ||= 'postgres://placeholder:placeholder@localhost:5432/placeholder';

const migrations = [
  ['002 — user_notifications (credit-expiry + inactivity email guards)', '../migrations/002-user-notifications.js'],
  ['003 — user address (tax purposes)', '../migrations/003-user-address.js'],
  ['004 — billing_transactions (BILL-004 canonical ledger)', '../migrations/004-billing-transactions.js'],
  ['005 — billing_disclosures (BILL-003 pre-charge disclosure audit)', '../migrations/005-billing-disclosures.js'],
  ['006 — users.default_payment_method_* (BILL-001 local default)', '../migrations/006-default-payment-method.js'],
  ['007 — email_sends + suppression columns (BILL-006, BILL-008)', '../migrations/007-email-sends.js'],
  ['008 — websites.last_connected_at (real plugin connection signal)', '../migrations/008-website-last-connected.js'],
  ['014 — websites.heartbeat_at (plugin checks in on its own)', '../migrations/014-website-heartbeat.js'],
  ['015 — website_limit for Grow (2) and Optimize (3)', '../migrations/015-plan-website-limits.js'],
] as const;
// NOTE: 009–013 are absent from this list and were before 014 was added. Left
// alone deliberately rather than fixed in passing — whoever added them either
// applied them by hand or excluded them on purpose, and guessing wrong here
// means handing someone SQL to run against production.

const rule = '-- ' + '─'.repeat(72);

async function main() {
  const out: string[] = [
    '-- ImproveSEO — pending migrations, safe to paste into the Supabase SQL editor.',
    '-- Every statement is idempotent: running this file twice is a no-op.',
    '--',
    '-- GENERATED by `npm run migrations:print`. Do not hand-edit — edit the',
    '-- migration under src/migrations/ and regenerate, or the file that runs in',
    '-- production will drift from the file in the repo.',
    '',
  ];

  for (const [title, path] of migrations) {
    const mod = await import(path);
    if (typeof mod.MIGRATION_SQL !== 'string') {
      throw new Error(`${path} does not export MIGRATION_SQL`);
    }
    out.push(rule, `-- ${title}`, rule, mod.MIGRATION_SQL.trim(), '');
  }

  process.stdout.write(out.join('\n') + '\n');
}

main().catch((err) => {
  console.error('Failed to print migrations:', err);
  process.exit(1);
});
